/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_ORG_UNIT_DEFINITION
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_ORG_UNIT   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_ORG_UNIT_HK
   hashdiff    : SAT_ORG_UNIT_DEFINITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_ORG_UNIT|' || (HUB_ORG_UNIT_BK__BRANCH_CODE))) as HUB_ORG_UNIT_HK
        , ACCOUNT_CATEGORY_CODE as ACCOUNTING_CATEGORY_CODE
        , REGISTER_FLAG as REGISTRATION_INDICATOR
        , NEAREST_DM_BRANCH as NEAREST_CONTROLLING_ORG_UNIT_REFERENCE
        , RECORD_DATE as SOURCE_RECORD_DATE
        , REASON_FOR_ACT_DEACT as ORG_UNIT_STATUS_REASON
        , 'BJAZ_BRANCH_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_branch_master') }}
    where (nullif(trim(BRANCH_CODE),'')) is not null
),

resolved as (
    select
        HUB_ORG_UNIT_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then ACCOUNTING_CATEGORY_CODE end) as ACCOUNTING_CATEGORY_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then REGISTRATION_INDICATOR end) as REGISTRATION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEAREST_CONTROLLING_ORG_UNIT_REFERENCE end) as NEAREST_CONTROLLING_ORG_UNIT_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then SOURCE_RECORD_DATE end) as SOURCE_RECORD_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ORG_UNIT_STATUS_REASON end) as ORG_UNIT_STATUS_REASON,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ORG_UNIT_HK
),

hashed as (
    select
        *,
        case when ACCOUNTING_CATEGORY_CODE is not null or REGISTRATION_INDICATOR is not null or NEAREST_CONTROLLING_ORG_UNIT_REFERENCE is not null or SOURCE_RECORD_DATE is not null or ORG_UNIT_STATUS_REASON is not null
                     then md5(upper(coalesce(cast(ACCOUNTING_CATEGORY_CODE as varchar), '') || '|' || coalesce(cast(REGISTRATION_INDICATOR as varchar), '') || '|' || coalesce(cast(NEAREST_CONTROLLING_ORG_UNIT_REFERENCE as varchar), '') || '|' || coalesce(cast(SOURCE_RECORD_DATE as varchar), '') || '|' || coalesce(cast(ORG_UNIT_STATUS_REASON as varchar), '')))
                end as SAT_ORG_UNIT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_ORG_UNIT_HK is not null
  and SAT_ORG_UNIT_DEFINITION_HASHDIFF is not null
